package com.bank.flink.bc;

import java.math.BigDecimal;

// A fraud rule broadcast to every instance.
class Rule {
    enum Type { MAX_AMOUNT, BLOCK_MERCHANT }

    private final String id;
    private final Type type;
    private final BigDecimal amountThreshold; // for MAX_AMOUNT
    private final String blockedMerchant;     // for BLOCK_MERCHANT

    Rule(String id, Type type, BigDecimal amountThreshold, String blockedMerchant) {
        this.id = id;
        this.type = type;
        this.amountThreshold = amountThreshold;
        this.blockedMerchant = blockedMerchant;
    }

    String getId() { return id; }
    Type getType() { return type; }
    BigDecimal getAmountThreshold() { return amountThreshold; }
    String getBlockedMerchant() { return blockedMerchant; }
}
