package com.bank.flink.bc;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// Stands in for Flink BroadcastState<String, Rule>. Updated identically on
// every instance (processBroadcastElement); read-only when screening txns.
class BroadcastRuleState {
    private static final Logger log = Logger.getLogger(BroadcastRuleState.class.getName());

    // rule id -> rule (the replicated map)
    private final Map<String, Rule> rules = new LinkedHashMap<>();

    // processBroadcastElement: the ONLY place rules are modified.
    void applyRuleUpdate(Rule rule) {
        rules.put(rule.getId(), rule);
        log.fine(() -> "Rule applied: " + rule.getId() + " type=" + rule.getType());
    }

    // processElement: READ-ONLY screening of a transaction against all rules.
    String screen(Txn txn) {
        for (Rule rule : rules.values()) {
            if (rule.getType() == Rule.Type.MAX_AMOUNT
                    && txn.getAmount().compareTo(rule.getAmountThreshold()) > 0) {
                return "FLAGGED by " + rule.getId() + " (amount " + txn.getAmount()
                        + " > " + rule.getAmountThreshold() + ")";
            }
            if (rule.getType() == Rule.Type.BLOCK_MERCHANT
                    && rule.getBlockedMerchant().equals(txn.getMerchant())) {
                return "BLOCKED by " + rule.getId() + " (merchant " + txn.getMerchant() + ")";
            }
        }
        return "PASS";
    }

    int ruleCount() { return rules.size(); }
}
