package com.bank.flink.bc;

import java.util.logging.Logger;

// One parallel operator instance, each with its OWN identical replica of
// the broadcast state (every instance receives every rule update).
class ParallelInstance {
    private static final Logger log = Logger.getLogger(ParallelInstance.class.getName());

    private final int instanceId;
    private final BroadcastRuleState ruleState = new BroadcastRuleState();

    ParallelInstance(int instanceId) {
        this.instanceId = instanceId;
    }

    // Broadcast delivery: every instance applies the SAME rule update.
    void onBroadcastRule(Rule rule) {
        ruleState.applyRuleUpdate(rule);
        log.info(() -> "Instance " + instanceId + " received broadcast rule "
                + rule.getId() + " (now holds " + ruleState.ruleCount() + " rules)");
    }

    // Main stream: screen a transaction against this instance's rule replica.
    void onTransaction(Txn txn) {
        String verdict = ruleState.screen(txn);
        log.info(() -> "Instance " + instanceId + " screened " + txn.getAccountId()
                + " amount " + txn.getAmount() + " merchant " + txn.getMerchant()
                + " -> " + verdict);
    }
}
