package com.bank.flink.bc;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: broadcast a rule to all instances, screen txns on different
// instances consistently, then update the rule and see all instances apply it.
public class BroadcastStateDemo {
    private static final Logger log = Logger.getLogger(BroadcastStateDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new BcLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Four parallel instances.
        List<ParallelInstance> instances = List.of(
            new ParallelInstance(0), new ParallelInstance(1),
            new ParallelInstance(2), new ParallelInstance(3));

        // Broadcast rule 1: flag any transaction over 500000 to ALL instances.
        Rule r1 = new Rule("R1", Rule.Type.MAX_AMOUNT, new BigDecimal("500000"), null);
        for (ParallelInstance i : instances) i.onBroadcastRule(r1);

        // Screen transactions on different instances (simulating keyed routing).
        instances.get(0).onTransaction(new Txn("SAV2001", new BigDecimal("600000"), "AMAZON"));
        instances.get(2).onTransaction(new Txn("CUR3001", new BigDecimal("250000"), "FLIPKART"));

        // Broadcast rule 2: block merchant CASINO7995 to ALL instances.
        Rule r2 = new Rule("R2", Rule.Type.BLOCK_MERCHANT, null, "CASINO7995");
        for (ParallelInstance i : instances) i.onBroadcastRule(r2);

        // Now the new rule takes effect everywhere immediately.
        instances.get(1).onTransaction(new Txn("SAV2001", new BigDecimal("1000"), "CASINO7995"));
        instances.get(3).onTransaction(new Txn("CUR3001", new BigDecimal("300000"), "CASINO7995"));
    }
}

// ─── Would be in BcLogFormatter.java in a real project ───
class BcLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
